const { useEffect, useRef, useState } = React;

const LAYOUTS = [
  { value: "first", label: "首位" },
  { value: "last", label: "末尾" },
  { value: "none", label: "没有" },
  { value: "two", label: "两个" },
];

const SUMMARY = "cursor-pointer select-none px-3 py-2 text-tau-body text-ink-1 hover:bg-hover";
const BODY = "border-t border-line-2 px-3 py-2 text-tau-meta text-ink-2";

// 每种结构对应的 HTML 源码行，summary 行高亮
const SOURCE = {
  first: ["<details{open}>", "  <summary>点击查看详细内容</summary>", "  <p>隐藏的详情内容</p>", "</details>"],
  last: ["<details{open}>", "  <p>隐藏的详情内容</p>", "  <summary>点击查看详细内容</summary>", "</details>"],
  none: ["<details{open}>", "  <p>隐藏的详情内容</p>", "</details>"],
  two: [
    "<details{open}>",
    "  <summary>点击查看详细内容</summary>",
    "  <p>隐藏的详情内容</p>",
    "  <summary>第二个 summary</summary>",
    "</details>",
  ],
};

const Details = ({ layout, detailsRef }) => {
  const body = (
    <div key="body" className={BODY}>
      隐藏的详情内容
    </div>
  );
  const summary = (
    <summary key="summary" className={SUMMARY}>
      点击查看详细内容
    </summary>
  );
  const children = {
    first: [summary, body],
    last: [body, summary],
    none: [body],
    two: [
      summary,
      body,
      <summary key="extra" className="px-3 pb-2 text-tau-meta text-ink-2">
        第二个 summary
      </summary>,
    ],
  }[layout];
  return (
    <details
      ref={detailsRef}
      // 没有 summary 时浏览器生成的默认标题无法加样式，给 details 留出内边距
      className={
        layout === "none"
          ? "overflow-hidden rounded-tau-sm border border-line-1 bg-surface p-2 text-tau-body text-ink-1"
          : "overflow-hidden rounded-tau-sm border border-line-1 bg-surface"
      }
    >
      {children}
    </details>
  );
};

const Component = () => {
  const detailsRef = useRef(null);
  const [layout, setLayout] = useState("first");
  const [open, setOpen] = useState(false);

  useEffect(() => {
    const details = detailsRef.current;
    // 换结构会重建 details，沿用之前的展开状态
    if (open) details.open = true;
    const handleToggle = () => setOpen(details.open);
    details.addEventListener("toggle", handleToggle);
    return () => details.removeEventListener("toggle", handleToggle);
  }, [layout]);

  const setProperty = value => {
    detailsRef.current.open = value;
    setOpen(detailsRef.current.open);
  };

  return (
    <div className="@container flex flex-col gap-3">
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,42%)]">
        <div className="min-h-[148px] min-w-0 rounded-tau-md border border-line-1 p-4">
          <Details key={layout} layout={layout} detailsRef={detailsRef} />
        </div>
        <pre className="m-0 min-w-0 overflow-x-auto rounded-tau-md border border-line-1 p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
          {SOURCE[layout].map((line, index) => (
            <div key={index} className={line.includes("summary") ? "rounded-tau-sm bg-accent-soft text-accent-text" : ""}>
              {line.replace("{open}", open ? " open" : "")}
            </div>
          ))}
        </pre>
      </div>
      <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
        <div className="flex items-center gap-2">
          <ui.Button variant="secondary" size="sm" onClick={() => setProperty(true)}>
            <span className="font-tau-mono">open = true</span>
          </ui.Button>
          <ui.Button variant="secondary" size="sm" onClick={() => setProperty(false)}>
            <span className="font-tau-mono">open = false</span>
          </ui.Button>
        </div>
        <code className="rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">details.open：{String(open)}</code>
      </div>
      <ui.RadioGroup label="summary 的位置" value={layout} onValueChange={setLayout} orientation="horizontal">
        {LAYOUTS.map(item => (
          <ui.Radio key={item.value} value={item.value} label={item.label} />
        ))}
      </ui.RadioGroup>
    </div>
  );
};

const { useEffect, useRef, useState } = React;

const FAQ = [
  { title: "什么是 HTML？", content: "HTML 是超文本标记语言，用于构建网页结构。" },
  { title: "什么是 CSS？", content: "CSS 是层叠样式表，用于控制网页的视觉表现。" },
  { title: "什么是 JavaScript？", content: "JavaScript 是一种脚本语言，用于实现网页的动态交互。" },
];

const Component = () => {
  const itemRefs = useRef([]);
  const [grouped, setGrouped] = useState(true);
  const [openStates, setOpenStates] = useState(FAQ.map(() => false));

  const sync = () => setOpenStates(itemRefs.current.map(details => Boolean(details?.open)));

  useEffect(() => {
    const items = [...itemRefs.current];
    items.forEach(details => details.addEventListener("toggle", sync));
    return () => items.forEach(details => details.removeEventListener("toggle", sync));
  }, []);

  // name 经特性设置，开关切换时同步增删
  useEffect(() => {
    itemRefs.current.forEach(details => (grouped ? details.setAttribute("name", "faq") : details.removeAttribute("name")));
    sync();
  }, [grouped]);

  const openAll = () => {
    itemRefs.current.forEach(details => {
      details.open = true;
    });
    sync();
  };
  const closeAll = () => {
    itemRefs.current.forEach(details => {
      details.open = false;
    });
    sync();
  };

  const openCount = openStates.filter(Boolean).length;

  return (
    <div className="@container flex flex-col gap-3">
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(220px,34%)]">
        <div className="flex min-w-0 flex-col gap-2 rounded-tau-md border border-line-1 p-3">
          {FAQ.map((item, index) => (
            <details
              key={item.title}
              ref={node => {
                itemRefs.current[index] = node;
              }}
              className="overflow-hidden rounded-tau-sm border border-line-1 bg-surface"
            >
              <summary className="cursor-pointer select-none px-3 py-2 text-tau-body text-ink-1 hover:bg-hover">{item.title}</summary>
              <div className="border-t border-line-2 px-3 py-2 text-tau-meta text-ink-2">{item.content}</div>
            </details>
          ))}
        </div>
        <div className="flex flex-col gap-2 rounded-tau-md border border-line-1 p-3">
          <span className="text-tau-sm text-ink-3">展开状态</span>
          {FAQ.map((item, index) => (
            <div key={item.title} className="flex items-center justify-between gap-2">
              <span className="min-w-0 truncate text-tau-meta text-ink-2">{item.title}</span>
              <ui.Tag color={openStates[index] ? "blue" : "gray"} className="shrink-0">
                {openStates[index] ? "open" : "closed"}
              </ui.Tag>
            </div>
          ))}
          <span className="mt-auto font-tau-mono text-tau-sm text-ink-3">展开数：{openCount}</span>
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
        <ui.Switch checked={grouped} onCheckedChange={setGrouped} label='name="faq"' size="sm" />
        <div className="flex items-center gap-2">
          <ui.Button variant="secondary" size="sm" onClick={openAll}>
            脚本全部展开
          </ui.Button>
          <ui.Button variant="ghost" size="sm" onClick={closeAll}>
            全部收起
          </ui.Button>
        </div>
        <code className="rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">
          {grouped ? '<details name="faq"> × 3' : "<details> × 3，未分组"}
        </code>
      </div>
    </div>
  );
};

const { useEffect, useRef, useState } = React;

const STATE_COLORS = { open: "blue", closed: "gray" };

const Component = () => {
  const detailsRef = useRef(null);
  const [log, setLog] = useState([]);
  const [action, setAction] = useState(null);

  useEffect(() => {
    const details = detailsRef.current;
    const handleToggle = event => {
      const entry = { id: Date.now() + Math.random(), oldState: event.oldState, newState: event.newState };
      setLog(current => [entry, ...current].slice(0, 6));
    };
    details.addEventListener("toggle", handleToggle);
    return () => details.removeEventListener("toggle", handleToggle);
  }, []);

  const toggleOnce = () => {
    const details = detailsRef.current;
    details.open = !details.open;
    setAction("open = !open（1 次）");
  };
  // 同一任务里连续改两次，toggle 事件会被合并成一个
  const toggleTwice = () => {
    const details = detailsRef.current;
    details.open = !details.open;
    details.open = !details.open;
    setAction("open = !open（同步 2 次）");
  };

  return (
    <div className="@container flex flex-col gap-3">
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,40%)]">
        <div className="min-h-[148px] min-w-0 rounded-tau-md border border-line-1 p-4">
          <details ref={detailsRef} className="overflow-hidden rounded-tau-sm border border-line-1 bg-surface">
            <summary className="cursor-pointer select-none px-3 py-2 text-tau-body text-ink-1 hover:bg-hover">点击触发 toggle 事件</summary>
            <div className="border-t border-line-2 px-3 py-2 text-tau-meta text-ink-2">展开后的详情内容，收起时会再次触发 toggle。</div>
          </details>
        </div>
        <div className="flex flex-col gap-2 rounded-tau-md border border-line-1 p-3">
          <div className="flex items-center justify-between gap-2">
            <span className="text-tau-sm text-ink-3">ToggleEvent</span>
            {log.length > 0 && (
              <ui.Button variant="ghost" size="sm" onClick={() => setLog([])}>
                清空
              </ui.Button>
            )}
          </div>
          {log.length ? (
            <ol className="m-0 flex list-none flex-col gap-1.5 p-0">
              {log.map(entry => (
                <li key={entry.id} className="flex items-center gap-2">
                  <ui.Tag color={STATE_COLORS[entry.oldState] ?? "gray"}>{entry.oldState ?? "undefined"}</ui.Tag>
                  <icons.ArrowRight className="size-3.5 shrink-0 text-ink-3" />
                  <ui.Tag color={STATE_COLORS[entry.newState] ?? "gray"}>{entry.newState ?? "undefined"}</ui.Tag>
                  {entry.oldState === entry.newState && <span className="ml-auto text-tau-sm text-warn">已合并</span>}
                </li>
              ))}
            </ol>
          ) : (
            <p className="m-0 text-tau-meta text-ink-3">点击 summary 或下方按钮</p>
          )}
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
        <div className="flex items-center gap-2">
          <ui.Button variant="secondary" size="sm" onClick={toggleOnce}>
            切换一次
          </ui.Button>
          <ui.Button variant="secondary" size="sm" onClick={toggleTwice}>
            同步切换两次
          </ui.Button>
        </div>
        {action && (
          <code className="min-w-0 break-all rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">{action}</code>
        )}
      </div>
    </div>
  );
};
